package a_17_basics;

public class A005_static_in_main {  
	
	 static void add() {
		
		int a=3;
		int b=1;
		
		System.out.println(a+b);
	}
	
	static void sub(int a, int b) {
		System.out.println(a-b);
	}

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		add();
		sub(10, 7);

	}

}
